public int findLargestSubstring(List<String> strings) {
    for (int len = strings.get(0).length(); len > 0; len--) {
        for (String lenString : new ArrayList<>(strings)) {
            if (lenString.length() >= len) {
                String reversed = new StringBuilder(lenString).reverse().toString();
                if (strings.contains(lenString) || strings.contains(reversed)) {
                    return len;
                }
            }
        }
    }
    return 0;
}

