public String sortString(String s) {
    s = s.replaceAll(" ", ""); // Remove spaces from the input string
    char[] chars = s.toCharArray();
    PriorityQueue<Character> minHeap = new PriorityQueue<>();
    PriorityQueue<Character> maxHeap = new PriorityQueue<>(Collections.reverseOrder());

    // Count the occurrences of each character
    Map<Character, Integer> countMap = new HashMap<>();
    for (char c : chars) {
        countMap.put(c, countMap.getOrDefault(c, 0) + 1);
    }

    // Add characters to the heaps
    for (Character c : countMap.keySet()) {
        if (countMap.get(c) > 0) {
            minHeap.offer(c);
            maxHeap.offer(c);
        }
    }

    String result = "";
    while (!minHeap.isEmpty() || !maxHeap.isEmpty()) {
        if (!minHeap.isEmpty()) {
            result += minHeap.poll();
            countMap.put(result.charAt(result.length() - 1), countMap.get(result.charAt(result.length() - 1)) - 1);
            if (countMap.get(result.charAt(result.length() - 1)) == 0) {
                countMap.remove(result.charAt(result.length() - 1));
