        int quotient = n / base;
        int remainder = n % base;

        if (remainder > 0 && remainder >= 1) {
            total += quotient * base + digit;
        } else {
            total += Math.max(0, quotient - 1) * base;
        }

        digit *= 10;
        base *= 10;
    }

    return total;
}

