public static int findSmallestInteger(int n) {
    // Convert the input number to a string to handle its digits easily
    String str = String.valueOf(n);

    // Find the smallest digit in the string
    char minDigit = str.charAt(str.indexOf(Character.MIN_VALUE));

    // Find all occurrences of the smallest digit
    int[] minOccurrences = new int[256];
    for (int i = 0; i < str.length(); i++) {
        if (str.charAt(i) == minDigit) {
            minOccurrences[str.charAt(i)]++;
        }
    }

    // Find the smallest index where the smallest digit can be placed
    int index = 0;
    for (int i = 0; i < minOccurrences.length(); i++) {
        if (minOccurrences[i] > 0) {
            index = i;
            break;
        }
    }

    // Find the character that can be placed in the smallest index to match the smallest digit
    char newDigit;
    for (int i = index; i < minOccurrences.length(); i++) {
        if ((newDigit = str.charAt(i)) != minDigit && minOccurrences[i] > 0) {
            break;
        }
