public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= 9; i++) {
        result.add(i);
        if (i * 10 <= n) {
            int num = i * 10;
            for (int j = 0; j < 10 && num + j <= n; j++) {
                result.add(num + j);
            }
        }
    }
    return result;
}

