    if (n <= 0) return 0; // No perfect squares exist for n <= 0

    int[] dp = new int[n + 1];
    dp[0] = 0; // Base case: 0 perfect squares sum up to 0

    for (int i = 1; i <= n; i++) {
        int minSquares = Integer.MAX_VALUE;
        for (int sqrt = 1; sqrt * sqrt <= i; sqrt++) {
            minSquares = Math.min(minSquares, dp[i - sqrt * sqrt]) + 1;
        }
        dp[i] = minSquares;
    }

    return dp[n];
}

